"""Prefix to Infix — scan right to left, combining two operands per operator.

Time: O(n)   Space: O(n)
"""


class Solution:
    def prefixToInfix(self, s: str) -> str:
        stack = []
        for ch in reversed(s):
            if ch.isalnum():
                stack.append(ch)
            else:
                left, right = stack.pop(), stack.pop()
                stack.append("(%s%s%s)" % (left, ch, right))
        return stack[-1]
